// --- DUAL OTP START ---
let otpPhone='';let otpEmail='';let otpMethod='email';
async function signup(){
  let st=document.getElementById('dbStatus');
  let emailRaw=(document.getElementById('myEmail')?.value||'').trim().toLowerCase();
  let phoneRaw=(document.getElementById('myPhone')?.value||'').trim();
  let useEmail=emailRaw.indexOf('@')>-1 && emailRaw.indexOf('.')>-1;
  let usePhone=phoneRaw.length>=9;
  if(!useEmail && !usePhone){toast('Enter your email OR phone number');return;}
  if(useEmail){otpMethod='email';otpEmail=emailRaw;} else {otpMethod='phone';otpPhone=normPhone(phoneRaw);}
  let dest = otpMethod==='email' ? otpEmail : otpPhone;
  if(st)st.textContent='Sending code…';
  let b=document.getElementById('sendCodeBtn');
  if(b)b.disabled=true;
  let r = otpMethod==='email' ? await supabaseClient.auth.signInWithOtp({email:otpEmail}) : await supabaseClient.auth.signInWithOtp({phone:otpPhone});
  if(b)setTimeout(()=>{b.disabled=false;b.textContent='Resend code';},30000);
  if(r.error){if(st)st.textContent=r.error.message;toast('Could not send code: '+r.error.message);if(b)b.disabled=false;return;}
  if(st)st.textContent='Code sent to '+dest;
  document.getElementById('otpBox').classList.remove('hidden');
  document.getElementById('otpCode').focus();
  toast(otpMethod==='email'?'Code sent by email - check inbox / spam':'Code sent by SMS');
}
async function verifyOtp(){
  let tok=document.getElementById('otpCode').value.trim();
  if(!/^\d{6}$/.test(tok)){toast('Enter the 6-digit code');return;}
  let v = otpMethod==='email' ? await supabaseClient.auth.verifyOtp({email:otpEmail,token:tok,type:'email'}) : await supabaseClient.auth.verifyOtp({phone:otpPhone,token:tok,type:'sms'});
  if(v.error){toast('Wrong or expired code');return;}
  let name=document.getElementById('myName').value.trim();
  let handle=document.getElementById('myHandle').value.trim();
  let r=await supabaseClient.rpc('ensure_profile',{p_name:name||null,p_handle:handle||null});
  if(r.error){let m=r.error.message||'';toast(m.includes('NAME_REQUIRED')?'New account — enter your name above, then tap Verify again':m.includes('NAME_TAKEN')?'That name is taken — choose another, then tap Verify':m.includes('NAME_INVALID')?'Name: max 30 chars, no quotes, commas or brackets':m);return;}
  enterApp(r.data,'Welcome, '+r.data.name);
}
// --- DUAL OTP END ---

